const D=window.RassData,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const safe=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
const brl=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const fmtDate=iso=>{if(!iso)return'-';const [y,m,d]=iso.split('-');return`${d}/${m}/${y}`};
const fmtDT=iso=>{try{return new Date(iso).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}catch{return'-'}};
const monthKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
const todayIso=()=>new Date().toISOString().slice(0,10);
const titles={dashboard:'Visão geral',appointments:'Agenda',clients:'Clientes',services:'Serviços',jewelry:'Joias & estoque',gallery:'Galeria',promotions:'Promoções',finance:'Financeiro',staff:'Equipe',notifications:'Notificações',settings:'Site & Studio',trash:'Lixeira & backup'};
let pendingServiceImage='',pendingJewelryImage='',pendingGalleryImage='',pendingMfaFactor='';

function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__to);window.__to=setTimeout(()=>t.classList.remove('show'),2800)}
function modal(id,open=true){$(id).classList.toggle('open',open)}
function closeAll(){$$('.admin-modal').forEach(m=>m.classList.remove('open'))}
function all(name){return D.get(name)}
function set(name,v){D.set(name,v)}
function sum(a){return a.reduce((n,x)=>n+Number(x||0),0)}
function statusClass(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,'-')}
function stockState(q){const lim=Number(all('settings').lowStockThreshold||2);q=Number(q||0);if(q<=0)return['Sem estoque','out'];if(q<=lim)return['Estoque baixo','low'];return['Em estoque','ok']}
function serviceById(id){return all('services').find(x=>x.id===id)}
function staffById(id){return all('staff').find(x=>x.id===id)}

function showTab(tab){$$('.admin-view').forEach(v=>v.classList.toggle('active',v.id===`tab-${tab}`));$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#pageTitle').textContent=titles[tab]||'Painel';renderAll()}
function initNav(){$$('[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));$$('[data-go]').forEach(b=>b.onclick=()=>showTab(b.dataset.go))}
function showMfaLogin(){
  $('#loginForm')?.classList.add('hidden');$('#mfaLoginForm')?.classList.remove('hidden');$('#mfaLoginCode')?.focus();$('#loginModeHint').textContent='Digite o código de 6 dígitos do seu aplicativo autenticador.'
}
function showPasswordLogin(){
  $('#mfaLoginForm')?.classList.add('hidden');$('#loginForm')?.classList.remove('hidden');if($('#mfaLoginCode'))$('#mfaLoginCode').value='';if($('#mfaLoginError'))$('#mfaLoginError').textContent='';$('#loginModeHint').textContent='Acesso protegido pelo Supabase · sessão expira após 30 min sem uso.'
}
async function initLogin(){
  const remote=!!window.RassRemote?.configured();
  $('#adminLoginEmailField')?.classList.remove('hidden');
  if($('#adminLoginEmail'))$('#adminLoginEmail').required=true;
  $('#loginModeHint').textContent='Acesso protegido pelo Supabase · sessão expira após 30 min sem uso.';
  if(!remote){
    $('#loginError').textContent='Configuração segura do Supabase não encontrada. O painel foi bloqueado.';
    $('#loginForm button[type="submit"]').disabled=true;
    return;
  }
  try{
    const session=await RassRemote.initAdmin();
    if(session?.mfaRequired){showMfaLogin()}
    else if(session?.ok){enterAdmin();return}
  }catch(err){
    const msg=String(err?.message||'');
    if(/HTTPS|localhost/i.test(msg))$('#loginError').textContent=msg;
  }
  let failures=0,lockedUntil=0;
  $('#loginForm').onsubmit=async e=>{
    e.preventDefault();const btn=e.submitter,now=Date.now();
    if(now<lockedUntil){$('#loginError').textContent=`Aguarde ${Math.ceil((lockedUntil-now)/1000)}s antes de tentar novamente.`;return}
    btn.disabled=true;$('#loginError').textContent='';
    try{
      const result=await RassRemote.login($('#adminLoginEmail').value.trim(),$('#adminPassword').value);
      failures=0;
      if(result?.mfaRequired){$('#adminPassword').value='';showMfaLogin();return}
      enterAdmin();toast('Painel conectado com segurança.');
    }catch(err){
      failures++;
      if(failures>=5){lockedUntil=Date.now()+60000;failures=0;$('#loginError').textContent='Muitas tentativas. Aguarde 60 segundos.'}
      else $('#loginError').textContent=err?.message||'Não foi possível entrar. Confira e-mail e senha.';
    }finally{btn.disabled=false}
  };
  $('#mfaLoginForm').onsubmit=async e=>{
    e.preventDefault();const btn=e.submitter;btn.disabled=true;$('#mfaLoginError').textContent='';
    try{await RassRemote.verifyMfa($('#mfaLoginCode').value);enterAdmin();toast('Verificação em duas etapas concluída.')}catch(err){$('#mfaLoginError').textContent=err?.message||'Código inválido.'}finally{btn.disabled=false}
  };
  $('#mfaBackBtn').onclick=async()=>{await RassRemote.logout();showPasswordLogin()};
  $('#logoutBtn').onclick=async()=>{await RassRemote.logout();location.reload()};
}
function enterAdmin(){$('#loginScreen').classList.add('hidden');$('#adminShell').classList.remove('hidden');$('#todayLabel').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'});renderAll();refreshMfaPanel()}

function renderNavBadges(){const apps=all('appointments'),j=all('jewelry'),notes=all('notifications');const p=apps.filter(a=>a.status==='Pendente').length,low=j.filter(x=>Number(x.qty)<=Number(all('settings').lowStockThreshold||2)).length,n=notes.filter(x=>!x.read).length;$('#navPendingAppointments').textContent=p||'';$('#navStockAlerts').textContent=low||'';$('#navNotifications').textContent=n||''}
function renderSiteModeQuick(){const s=all('settings'),b=$('#siteModeQuick');b.textContent=s.siteOpen?'● Agenda aberta':'● Agenda pausada';b.className=`site-mode-pill ${s.siteOpen?'on':'off'}`;b.onclick=()=>{s.siteOpen=!s.siteOpen;set('settings',s);D.notify('Modo do site alterado',s.siteOpen?'Agendamentos online ativados.':'Novos agendamentos pausados.','system');renderAll();toast(s.siteOpen?'Agenda online ativada.':'Agenda online pausada.')}}

function renderDashboard(){const apps=all('appointments'),srv=all('services'),j=all('jewelry'),clients=all('clients'),tx=all('transactions'),today=todayIso(),mk=monthKey();const todayApps=apps.filter(a=>a.date===today&&!['Cancelado','Recusado'].includes(a.status)).sort((a,b)=>a.time.localeCompare(b.time));const pending=apps.filter(a=>a.status==='Pendente').length;const low=j.filter(x=>Number(x.qty)<=Number(all('settings').lowStockThreshold||2)).length;const monthTx=tx.filter(t=>String(t.date||'').startsWith(mk));const income=sum(monthTx.filter(t=>t.type==='entrada').map(t=>t.amount)),expense=sum(monthTx.filter(t=>t.type==='saida').map(t=>t.amount));$('#statGrid').innerHTML=`<article class="stat-card"><small>HOJE</small><strong>${todayApps.length}</strong><span>agendamento${todayApps.length===1?'':'s'}</span></article><article class="stat-card"><small>PENDENTES</small><strong>${pending}</strong><span>aguardando confirmação</span></article><article class="stat-card"><small>CLIENTES</small><strong>${clients.length}</strong><span>cadastrados</span></article><article class="stat-card"><small>SERVIÇOS</small><strong>${srv.filter(x=>x.active!==false).length}</strong><span>${srv.filter(x=>x.type==='Unhas').length} de unhas</span></article><article class="stat-card"><small>ESTOQUE</small><strong>${low}</strong><span>itens em atenção</span></article><article class="stat-card"><small>SALDO DO MÊS</small><strong class="money-small">${brl(income-expense)}</strong><span>${brl(income)} em entradas</span></article>`;
$('#todayAppointments').innerHTML=todayApps.length?`<div class="mini-list">${todayApps.slice(0,8).map(a=>`<div class="mini-row"><time>${safe(a.time)}</time><div><strong>${safe(a.name)}</strong><span>${safe(a.type||'')} · ${safe(a.service)}</span></div><span class="status-pill ${statusClass(a.status)}">${safe(a.status)}</span></div>`).join('')}</div>`:'<div class="empty-admin">Nenhum horário para hoje.</div>';
const alerts=[];if(pending)alerts.push(`<button data-go="appointments"><strong>${pending} agendamento${pending===1?'':'s'} pendente${pending===1?'':'s'}</strong><span>Confirmar ou responder →</span></button>`);if(low)alerts.push(`<button data-go="jewelry"><strong>${low} item${low===1?'':'s'} com estoque baixo/zero</strong><span>Revisar estoque →</span></button>`);const unread=all('notifications').filter(x=>!x.read).length;if(unread)alerts.push(`<button data-go="notifications"><strong>${unread} notificação${unread===1?'':'ões'} não lida${unread===1?'':'s'}</strong><span>Abrir central →</span></button>`);if(!all('settings').siteOpen)alerts.push(`<button data-go="settings"><strong>Agenda online está pausada</strong><span>Alterar modo do site →</span></button>`);$('#studioAlerts').innerHTML=alerts.length?`<div class="alert-stack">${alerts.join('')}</div>`:'<div class="empty-admin">Tudo certo por aqui.</div>';$$('#studioAlerts [data-go]').forEach(b=>b.onclick=()=>showTab(b.dataset.go));
const next7=[...Array(7)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()+i);const iso=d.toISOString().slice(0,10);return{label:d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.',''),count:apps.filter(a=>a.date===iso&&!['Cancelado','Recusado'].includes(a.status)).length}});const mx=Math.max(1,...next7.map(x=>x.count));$('#weekChart').innerHTML=next7.map(x=>`<div><b style="height:${Math.max(8,(x.count/mx)*100)}%"></b><strong>${x.count}</strong><span>${x.label}</span></div>`).join('');$('#financeSummary').innerHTML=`<div class="finance-mini"><div><span>Entradas</span><strong>${brl(income)}</strong></div><div><span>Saídas</span><strong>${brl(expense)}</strong></div><div class="balance"><span>Saldo</span><strong>${brl(income-expense)}</strong></div></div>`;const valid=apps.filter(a=>!['Cancelado','Recusado'].includes(a.status)),countBy=(field)=>valid.reduce((m,a)=>(m[a[field]||'—']=(m[a[field]||'—']||0)+1,m),{}),topOf=obj=>Object.entries(obj).sort((a,b)=>b[1]-a[1])[0]||['—',0],topService=topOf(countBy('service')),topType=topOf(countBy('type')),topTime=topOf(countBy('time')),paid=apps.filter(a=>a.status==='Concluído'&&Number(a.amount)>0),ticket=paid.length?sum(paid.map(a=>a.amount))/paid.length:0;$('#studioInsights').innerHTML=`<article><small>SERVIÇO MAIS PROCURADO</small><strong>${safe(topService[0])}</strong><span>${topService[1]} pedido${topService[1]===1?'':'s'}</span></article><article><small>ÁREA MAIS PROCURADA</small><strong>${safe(topType[0])}</strong><span>${topType[1]} agendamento${topType[1]===1?'':'s'}</span></article><article><small>HORÁRIO MAIS PEDIDO</small><strong>${safe(topTime[0])}</strong><span>com base na agenda</span></article><article><small>TICKET MÉDIO</small><strong>${brl(ticket)}</strong><span>atendimentos concluídos</span></article>`}

function renderAppointments(){let items=all('appointments').slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const view=$('#appointmentView')?.value,d=$('#appointmentDateFilter')?.value,st=$('#appointmentStatusFilter')?.value,tp=$('#appointmentTypeFilter')?.value;const today=todayIso();if(view==='today')items=items.filter(x=>x.date===today);if(view==='week'){const end=new Date();end.setDate(end.getDate()+6);const endIso=end.toISOString().slice(0,10);items=items.filter(x=>x.date>=today&&x.date<=endIso)}if(view==='month')items=items.filter(x=>String(x.date).startsWith(monthKey()));if(d)items=items.filter(x=>x.date===d);if(st)items=items.filter(x=>x.status===st);if(tp)items=items.filter(x=>x.type===tp);$('#appointmentTable').innerHTML=items.map(a=>`<tr><td>${fmtDate(a.date)}</td><td><strong>${safe(a.time)}</strong></td><td><strong>${safe(a.name)}</strong><small class="table-sub">${safe(a.phone||'')}</small></td><td><span class="area-chip ${a.type==='Unhas'?'nails':''}">${safe(a.type||'Piercing')}</span><strong>${safe(a.service)}</strong></td><td>${safe(a.staff||staffById(a.staffId)?.name||'-')}</td><td>${Number(a.amount)>0?brl(a.amount):'<small>Sob consulta</small>'}</td><td><select class="status-select ${statusClass(a.status)}" data-app-status="${a.id}">${['Pendente','Confirmado','Concluído','Cancelado','Recusado'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><div class="row-actions"><button data-edit-app="${a.id}">Editar</button><button class="danger" data-delete-app="${a.id}">Excluir</button></div></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty-admin">Nenhum agendamento encontrado.</div></td></tr>';$$('[data-app-status]').forEach(s=>s.onchange=()=>updateAppointmentStatus(s.dataset.appStatus,s.value));$$('[data-edit-app]').forEach(b=>b.onclick=()=>openAppointment(b.dataset.editApp));$$('[data-delete-app]').forEach(b=>b.onclick=()=>{if(confirm('Mover este agendamento para a lixeira?')){D.remove('appointments',b.dataset.deleteApp,true);renderAll();toast('Agendamento movido para a lixeira.')}});renderBlocked()}
function updateAppointmentStatus(id,status){const arr=all('appointments'),a=arr.find(x=>x.id===id);if(!a)return;const prev=a.status;a.status=status;set('appointments',arr);if(status==='Concluído'&&prev!=='Concluído'&&Number(a.amount)>0){const tx=all('transactions');if(!tx.some(t=>t.appointmentId===a.id)){tx.push({id:D.uid('tx'),type:'entrada',date:a.date,description:`${a.service} · ${a.name}`,amount:Number(a.amount),payment:a.payment||'Não definido',appointmentId:a.id,createdAt:D.nowIso()});set('transactions',tx)}}D.notify('Agendamento atualizado',`${a.name} · ${status}`,'appointment',{appointmentId:id});renderAll();toast('Status atualizado.')}
function renderBlocked(){const b=all('blocked').slice().sort((a,b)=>a.date.localeCompare(b.date));$('#blockedStrip').innerHTML=b.length?b.slice(0,10).map(x=>`<span><strong>${fmtDate(x.date)}</strong> ${x.allDay?'dia inteiro':x.time} · ${safe(staffById(x.staffId)?.name||'Todos')} <button data-remove-block="${x.id}">×</button></span>`).join(''):'<small>Nenhum bloqueio de agenda ativo.</small>';$$('[data-remove-block]').forEach(btn=>btn.onclick=()=>{D.remove('blocked',btn.dataset.removeBlock,false);renderAll();toast('Bloqueio removido.')})}
function fillAppointmentOptions(type='Piercing',serviceId='',staffId=''){const ss=all('services').filter(s=>s.active!==false&&s.type===type);$('#appService').innerHTML=ss.map(s=>`<option value="${s.id}" ${s.id===serviceId?'selected':''}>${safe(s.name)}</option>`).join('');const staff=all('staff').filter(s=>s.active!==false&&(s.specialties||[]).includes(type));$('#appStaff').innerHTML=staff.map(s=>`<option value="${s.id}" ${s.id===staffId?'selected':''}>${safe(s.name)}</option>`).join('')}
function openAppointment(id=''){const f=$('#appointmentForm');f.reset();$('#appointmentId').value='';$('#appointmentFormTitle').textContent=id?'Editar agendamento':'Novo agendamento';let a=null;if(id)a=all('appointments').find(x=>x.id===id);const type=a?.type||'Piercing';$('#appType').value=type;fillAppointmentOptions(type,a?.serviceId||'',a?.staffId||'');if(a){$('#appointmentId').value=a.id;$('#appName').value=a.name||'';$('#appPhone').value=a.phone||'';$('#appEmail').value=a.email||'';$('#appDate').value=a.date||'';$('#appTime').value=a.time||'';$('#appAmount').value=a.amount||0;$('#appStatus').value=a.status||'Pendente';$('#appPayment').value=a.payment||'';$('#appNotes').value=a.notes||''}else{$('#appDate').value=todayIso();$('#appStatus').value='Confirmado'}modal('#appointmentModal')}

function renderClients(){const apps=all('appointments');$('#clientGrid').innerHTML=all('clients').slice().sort((a,b)=>(b.lastSeen||'').localeCompare(a.lastSeen||'')).map(c=>{const hist=apps.filter(a=>a.clientId===c.id||String(a.phone||'').replace(/\D/g,'')===String(c.phone||'').replace(/\D/g,''));const last=hist.slice().sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time))[0];return`<article class="client-card"><div class="client-avatar">${safe((c.name||'C').slice(0,1).toUpperCase())}</div><div class="client-info"><small>CLIENTE</small><h3>${safe(c.name)}</h3><p>${safe(c.phone||'Sem telefone')} ${c.email?`· ${safe(c.email)}`:''}</p><div class="client-stats"><span><strong>${hist.length}</strong> atendimento${hist.length===1?'':'s'}</span><span>Último: <strong>${last?fmtDate(last.date):'—'}</strong></span></div>${c.notes?`<blockquote>${safe(c.notes)}</blockquote>`:''}</div><div class="client-actions"><button data-edit-client="${c.id}">Editar</button><button data-client-history="${c.id}">Histórico</button><button class="danger" data-delete-client="${c.id}">Excluir</button></div></article>`}).join('')||'<div class="empty-admin">Nenhum cliente cadastrado ainda.</div>';$$('[data-edit-client]').forEach(b=>b.onclick=()=>openClient(b.dataset.editClient));$$('[data-client-history]').forEach(b=>b.onclick=()=>{const c=all('clients').find(x=>x.id===b.dataset.clientHistory);const hist=apps.filter(a=>a.clientId===c.id||String(a.phone||'').replace(/\D/g,'')===String(c.phone||'').replace(/\D/g,'')).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));alert(hist.length?hist.map(a=>`${fmtDate(a.date)} ${a.time} — ${a.service} — ${a.status}`).join('\n'):'Sem histórico de agendamentos.')});$$('[data-delete-client]').forEach(b=>b.onclick=()=>{if(confirm('Mover cliente para a lixeira?')){D.remove('clients',b.dataset.deleteClient,true);renderAll()}})}
function openClient(id=''){const f=$('#clientForm');f.reset();$('#clientId').value='';$('#clientFormTitle').textContent=id?'Editar cliente':'Novo cliente';if(id){const c=all('clients').find(x=>x.id===id);if(!c)return;$('#clientId').value=c.id;$('#clientAdminName').value=c.name||'';$('#clientAdminPhone').value=c.phone||'';$('#clientAdminEmail').value=c.email||'';$('#clientAdminNotes').value=c.notes||''}modal('#clientModal')}

function renderServices(){let items=all('services'),filter=$('#serviceAdminFilter')?.value;if(filter)items=items.filter(s=>s.type===filter);$('#serviceAdminGrid').innerHTML=items.map(s=>`<article class="admin-service-card ${s.active===false?'is-inactive':''}"><div class="admin-service-image"><img src="${safe(s.image)}" alt="${safe(s.name)}"><span class="area-chip ${s.type==='Unhas'?'nails':''}">${safe(s.type||'Piercing')}</span>${s.featured?'<i>DESTAQUE</i>':''}</div><div class="admin-service-card-body"><div class="card-title-row"><h3>${safe(s.name)}</h3><label class="mini-toggle"><input type="checkbox" data-toggle-service="${s.id}" ${s.active!==false?'checked':''}><span></span></label></div><p>${safe(s.description)}</p><div class="admin-card-meta"><span>${Number(s.price)>0?brl(s.price):'Sob consulta'}</span><span>${Number(s.duration||60)} min · ${safe(s.category||'')}</span></div><div class="admin-card-actions"><button data-edit-service="${s.id}">Editar</button><button class="danger" data-delete-service="${s.id}">Excluir</button></div></div></article>`).join('')||'<div class="empty-admin">Nenhum serviço cadastrado.</div>';$$('[data-toggle-service]').forEach(x=>x.onchange=()=>{const a=all('services'),s=a.find(i=>i.id===x.dataset.toggleService);s.active=x.checked;set('services',a);renderAll()});$$('[data-edit-service]').forEach(b=>b.onclick=()=>openService(b.dataset.editService));$$('[data-delete-service]').forEach(b=>b.onclick=()=>{if(confirm('Mover serviço para a lixeira?')){D.remove('services',b.dataset.deleteService,true);renderAll();toast('Serviço movido para a lixeira.')}})}
function openService(id=''){pendingServiceImage='';$('#serviceForm').reset();$('#serviceId').value='';$('#servicePreview').classList.remove('show');$('#serviceFormTitle').textContent=id?'Editar serviço':'Novo serviço';if(id){const s=all('services').find(x=>x.id===id);$('#serviceId').value=s.id;$('#serviceType').value=s.type||'Piercing';$('#serviceName').value=s.name;$('#serviceCategory').value=s.category||'';$('#servicePrice').value=s.price||0;$('#serviceDuration').value=s.duration||60;$('#serviceDescription').value=s.description||'';$('#serviceImage').value=s.image||'';$('#serviceActive').checked=s.active!==false;$('#serviceFeatured').checked=!!s.featured;preview('#servicePreview',s.image)}modal('#serviceModal')}

function renderJewelry(){const items=all('jewelry'),lim=Number(all('settings').lowStockThreshold||2);const total=sum(items.map(x=>x.qty)),low=items.filter(x=>Number(x.qty)<=lim).length,out=items.filter(x=>Number(x.qty)<=0).length;$('#stockSummary').innerHTML=`<div><small>UNIDADES</small><strong>${total}</strong></div><div><small>ESTOQUE BAIXO</small><strong>${low}</strong></div><div><small>ZERADOS</small><strong>${out}</strong></div>`;$('#jewelryTable').innerHTML=items.map(j=>{const [txt,cls]=stockState(j.qty);return`<tr class="${j.active===false?'row-muted':''}"><td><div class="table-product"><img src="${safe(j.image)}"><strong>${safe(j.name)}</strong></div></td><td>${safe(j.category)}</td><td>${safe(j.material||'-')}</td><td>${brl(j.price)}</td><td><div class="qty-control"><button data-qty="${j.id}" data-delta="-1">−</button><strong>${Number(j.qty)}</strong><button data-qty="${j.id}" data-delta="1">+</button></div></td><td><span class="stock-pill ${cls}">${txt}</span></td><td><label class="mini-toggle"><input type="checkbox" data-toggle-jewelry="${j.id}" ${j.active!==false?'checked':''}><span></span></label></td><td><div class="row-actions"><button data-edit-jewelry="${j.id}">Editar</button><button class="danger" data-delete-jewelry="${j.id}">Excluir</button></div></td></tr>`}).join('');$$('[data-qty]').forEach(b=>b.onclick=()=>{const arr=all('jewelry'),j=arr.find(x=>x.id===b.dataset.qty);j.qty=Math.max(0,Number(j.qty)+Number(b.dataset.delta));set('jewelry',arr);renderAll()});$$('[data-toggle-jewelry]').forEach(x=>x.onchange=()=>{const a=all('jewelry'),j=a.find(i=>i.id===x.dataset.toggleJewelry);j.active=x.checked;set('jewelry',a);renderAll()});$$('[data-edit-jewelry]').forEach(b=>b.onclick=()=>openJewelry(b.dataset.editJewelry));$$('[data-delete-jewelry]').forEach(b=>b.onclick=()=>{if(confirm('Mover joia para a lixeira?')){D.remove('jewelry',b.dataset.deleteJewelry,true);renderAll()}})}
function openJewelry(id=''){pendingJewelryImage='';$('#jewelryForm').reset();$('#jewelryId').value='';$('#jewelryPreview').classList.remove('show');$('#jewelryFormTitle').textContent=id?'Editar joia':'Nova joia';if(id){const j=all('jewelry').find(x=>x.id===id);$('#jewelryId').value=j.id;$('#jewelryName').value=j.name;$('#jewelryCategory').value=j.category;$('#jewelryMaterial').value=j.material||'';$('#jewelryPrice').value=j.price||0;$('#jewelryQty').value=j.qty||0;$('#jewelryDescription').value=j.description||'';$('#jewelryImage').value=j.image||'';$('#jewelryActive').checked=j.active!==false;preview('#jewelryPreview',j.image)}modal('#jewelryModalAdmin')}

function renderGalleryAdmin(){let items=all('gallery'),f=$('#galleryAdminFilter')?.value;if(f)items=items.filter(g=>g.type===f);$('#galleryAdminGrid').innerHTML=items.map(g=>`<article class="gallery-admin-card ${g.active===false?'is-inactive':''}"><img src="${safe(g.image)}"><div class="gallery-admin-overlay"><span class="area-chip ${g.type==='Unhas'?'nails':''}">${safe(g.type)}</span>${g.featured?'<i>DESTAQUE</i>':''}<h3>${safe(g.title)}</h3><div><button data-edit-gallery="${g.id}">Editar</button><button class="danger" data-delete-gallery="${g.id}">Excluir</button></div></div></article>`).join('')||'<div class="empty-admin">Nenhuma foto nessa categoria.</div>';$$('[data-edit-gallery]').forEach(b=>b.onclick=()=>openGallery(b.dataset.editGallery));$$('[data-delete-gallery]').forEach(b=>b.onclick=()=>{if(confirm('Mover foto para a lixeira?')){D.remove('gallery',b.dataset.deleteGallery,true);renderAll()}})}
function openGallery(id=''){pendingGalleryImage='';$('#galleryForm').reset();$('#galleryId').value='';$('#galleryPreview').classList.remove('show');$('#galleryFormTitle').textContent=id?'Editar foto':'Nova foto';if(id){const g=all('gallery').find(x=>x.id===id);$('#galleryId').value=g.id;$('#galleryType').value=g.type;$('#galleryTitle').value=g.title;$('#galleryImage').value=g.image;$('#galleryActive').checked=g.active!==false;$('#galleryFeatured').checked=!!g.featured;preview('#galleryPreview',g.image)}modal('#galleryModal')}

function renderPromotions(){const items=all('promotions').slice().sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));$('#promotionAdminGrid').innerHTML=items.map(p=>`<article class="promo-admin-card ${p.active===false?'is-inactive':''}"><div><small>${safe(p.type||'Studio')} · ${p.active!==false?'ATIVA':'PAUSADA'}</small><h3>${safe(p.title)}</h3><p>${safe(p.description||'')}</p>${p.discount?`<strong>${safe(p.discount)}</strong>`:''}<span>${p.startDate?fmtDate(p.startDate):'Sem início'} → ${p.endDate?fmtDate(p.endDate):'Sem fim'}</span></div><div class="admin-card-actions"><button data-edit-promotion="${p.id}">Editar</button><button class="danger" data-delete-promotion="${p.id}">Excluir</button></div></article>`).join('')||'<div class="empty-admin">Nenhuma promoção criada.</div>';$$('[data-edit-promotion]').forEach(b=>b.onclick=()=>openPromotion(b.dataset.editPromotion));$$('[data-delete-promotion]').forEach(b=>b.onclick=()=>{if(confirm('Mover promoção para a lixeira?')){D.remove('promotions',b.dataset.deletePromotion,true);renderAll()}})}
function openPromotion(id=''){const f=$('#promotionForm');f.reset();$('#promotionId').value='';$('#promotionFormTitle').textContent=id?'Editar promoção':'Nova promoção';if(id){const p=all('promotions').find(x=>x.id===id);$('#promotionId').value=p.id;$('#promotionType').value=p.type||'Studio';$('#promotionDiscount').value=p.discount||'';$('#promotionTitle').value=p.title;$('#promotionDescription').value=p.description||'';$('#promotionStart').value=p.startDate||'';$('#promotionEnd').value=p.endDate||'';$('#promotionActive').checked=p.active!==false}modal('#promotionModal')}

function financeMonths(){const keys=new Set([monthKey(),...all('transactions').map(t=>String(t.date||'').slice(0,7)).filter(Boolean)]);return[...keys].sort().reverse()}
function renderFinance(){const sel=$('#financeMonth');const current=sel.value||monthKey();sel.innerHTML=financeMonths().map(m=>`<option value="${m}" ${m===current?'selected':''}>${new Date(m+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</option>`).join('');const mk=sel.value||current,tx=all('transactions').filter(t=>String(t.date).startsWith(mk)).sort((a,b)=>b.date.localeCompare(a.date)),income=sum(tx.filter(t=>t.type==='entrada').map(t=>t.amount)),expense=sum(tx.filter(t=>t.type==='saida').map(t=>t.amount)),completed=all('appointments').filter(a=>a.status==='Concluído'&&String(a.date).startsWith(mk));$('#financeCards').innerHTML=`<article><small>ENTRADAS</small><strong>${brl(income)}</strong></article><article><small>SAÍDAS</small><strong>${brl(expense)}</strong></article><article><small>SALDO</small><strong>${brl(income-expense)}</strong></article><article><small>ATENDIMENTOS CONCLUÍDOS</small><strong>${completed.length}</strong></article>`;$('#transactionTable').innerHTML=tx.map(t=>`<tr><td>${fmtDate(t.date)}</td><td><span class="finance-type ${t.type}">${t.type==='entrada'?'Entrada':'Saída'}</span></td><td>${safe(t.description)}</td><td>${safe(t.payment||'-')}</td><td><strong>${t.type==='saida'?'- ':'+ '}${brl(t.amount)}</strong></td><td><button class="danger-link" data-delete-tx="${t.id}">Excluir</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-admin">Nenhum lançamento neste mês.</div></td></tr>';$('#completedServices').innerHTML=completed.length?`<div class="mini-list">${completed.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<div class="mini-row"><time>${fmtDate(a.date)}</time><div><strong>${safe(a.service)}</strong><span>${safe(a.name)} · ${safe(a.type)}</span></div><strong>${Number(a.amount)>0?brl(a.amount):'—'}</strong></div>`).join('')}</div>`:'<div class="empty-admin">Nenhum atendimento concluído.</div>';$$('[data-delete-tx]').forEach(b=>b.onclick=()=>{if(confirm('Excluir lançamento financeiro?')){D.remove('transactions',b.dataset.deleteTx,false);renderAll()}})}

function renderStaff(){const apps=all('appointments');$('#staffGrid').innerHTML=all('staff').map(s=>`<article class="staff-admin-card ${s.active===false?'is-inactive':''}"><div class="staff-big-avatar">${safe((s.name||'R').slice(0,1))}</div><div><small>${s.active!==false?'ATIVA':'INATIVA'}</small><h3>${safe(s.name)}</h3><p>${safe((s.specialties||[]).join(' · '))}</p><span>${apps.filter(a=>a.staffId===s.id).length} agendamento${apps.filter(a=>a.staffId===s.id).length===1?'':'s'} registrado${apps.filter(a=>a.staffId===s.id).length===1?'':'s'}</span></div><div class="admin-card-actions"><button data-edit-staff="${s.id}">Editar</button><button class="danger" data-delete-staff="${s.id}">Excluir</button></div></article>`).join('');$$('[data-edit-staff]').forEach(b=>b.onclick=()=>openStaff(b.dataset.editStaff));$$('[data-delete-staff]').forEach(b=>b.onclick=()=>{if(all('staff').length<=1){alert('Mantenha pelo menos uma profissional cadastrada.');return}if(confirm('Mover profissional para a lixeira?')){D.remove('staff',b.dataset.deleteStaff,true);renderAll()}})}
function openStaff(id=''){const f=$('#staffForm');f.reset();$('#staffId').value='';$('#staffFormTitle').textContent=id?'Editar profissional':'Nova profissional';if(id){const s=all('staff').find(x=>x.id===id);$('#staffId').value=s.id;$('#staffName').value=s.name;$('#staffPhone').value=s.phone||'';$('#staffPiercing').checked=(s.specialties||[]).includes('Piercing');$('#staffNails').checked=(s.specialties||[]).includes('Unhas');$('#staffNotes').value=s.notes||'';$('#staffActive').checked=s.active!==false}else{$('#staffPiercing').checked=true;$('#staffNails').checked=true}modal('#staffModal')}

function renderNotifications(){const items=all('notifications');$('#notificationList').innerHTML=items.map(n=>`<article class="notification-item ${n.read?'':'unread'}"><span class="notification-icon">${n.kind==='appointment'?'□':n.kind==='quote'?'↗':n.kind==='stock'?'◇':'●'}</span><div><small>${fmtDT(n.createdAt)}</small><h3>${safe(n.title)}</h3><p>${safe(n.message||'')}</p></div><div><button data-read-note="${n.id}">${n.read?'Não lido':'Marcar lido'}</button><button class="danger" data-delete-note="${n.id}">×</button></div></article>`).join('')||'<div class="empty-admin">Sem notificações.</div>';$$('[data-read-note]').forEach(b=>b.onclick=()=>{const a=all('notifications'),n=a.find(x=>x.id===b.dataset.readNote);n.read=!n.read;set('notifications',a);renderAll()});$$('[data-delete-note]').forEach(b=>b.onclick=()=>{D.remove('notifications',b.dataset.deleteNote,false);renderAll()})}

function fillSettings(){const s=all('settings');if(!$('#settingStudioName'))return;$('#settingSiteOpen').checked=!!s.siteOpen;$('#settingSiteNotice').value=s.siteNotice||'';$('#settingLowStock').value=s.lowStockThreshold??2;$('#settingStudioName').value=s.studioName||'';$('#settingInstagram').value=s.instagram||'';$('#settingInstagramUrl').value=s.instagramUrl||'';$('#settingWhatsapp').value=s.whatsapp||'';$('#settingLocation').value=s.location||'';$('#settingHours').value=s.hours||'';$('#settingHeroEyebrow').value=s.heroEyebrow||'';$('#settingHeroLine1').value=s.heroLine1||'Rass Studio.';$('#settingHeroLine2').value=s.heroLine2||'Seu estilo.';$('#settingHeroLine3').value=s.heroLine3||'Sua expressão.';$('#settingHeroSubtitle').value=s.heroSubtitle||'';$('#settingHeroPrimary').value=s.heroPrimary||'';$('#settingHeroSecondary').value=s.heroSecondary||'';$('#settingShowJewelry').checked=s.showJewelry!==false;$('#settingShowGallery').checked=s.showGallery!==false;$('#settingShowFaq').checked=s.showFaq!==false;$('#settingStartHour').value=s.startHour??9;$('#settingEndHour').value=s.endHour??18;$('#settingInterval').value=String(s.interval||60);const days=[['Dom',0],['Seg',1],['Ter',2],['Qua',3],['Qui',4],['Sex',5],['Sáb',6]];$('#dayChecks').innerHTML=days.map(([n,v])=>`<label class="day-chip"><input type="checkbox" value="${v}" ${(s.workDays||[]).map(Number).includes(v)?'checked':''}><span>${n}</span></label>`).join('')}

function renderTrash(){const items=all('trash');$('#trashList').innerHTML=items.map(t=>`<div class="trash-row"><div><strong>${safe(t.item?.name||t.item?.title||t.item?.service||'Item')}</strong><span>${safe(t.entity)} · excluído em ${fmtDT(t.deletedAt)}</span></div><div><button data-restore-trash="${t.id}">Restaurar</button><button class="danger" data-purge-trash="${t.id}">Excluir definitivo</button></div></div>`).join('')||'<div class="empty-admin">A lixeira está vazia.</div>';$$('[data-restore-trash]').forEach(b=>b.onclick=()=>{const tr=all('trash'),idx=tr.findIndex(x=>x.id===b.dataset.restoreTrash);if(idx<0)return;const item=tr[idx],arr=all(item.entity);arr.push(item.item);set(item.entity,arr);tr.splice(idx,1);set('trash',tr);renderAll();toast('Item restaurado.')});$$('[data-purge-trash]').forEach(b=>b.onclick=()=>{set('trash',all('trash').filter(x=>x.id!==b.dataset.purgeTrash));renderAll()})}

function makeTablesResponsive(){document.querySelectorAll('.admin-table').forEach(table=>{const labels=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());table.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>td.setAttribute('data-label',labels[i]||'')))})}
function renderAll(){renderNavBadges();renderSiteModeQuick();renderDashboard();renderAppointments();renderClients();renderServices();renderJewelry();renderGalleryAdmin();renderPromotions();renderFinance();renderStaff();renderNotifications();fillSettings();renderTrash();makeTablesResponsive()}

function preview(sel,src){const p=$(sel);if(!src){p.classList.remove('show');p.innerHTML='';return}p.innerHTML=`<img src="${safe(src)}" alt="Prévia">`;p.classList.add('show')}
function fileToDataURL(file){return new Promise((resolve,reject)=>{const im=new Image(),r=new FileReader();r.onload=()=>{im.onload=()=>{const max=1100,scale=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.74))};im.onerror=reject;im.src=r.result};r.onerror=reject;r.readAsDataURL(file)})}
function initForms(){$$('[data-close-admin-modal]').forEach(x=>x.onclick=closeAll);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeAll()});
$$('[data-new-service]').forEach(b=>b.onclick=()=>openService());$$('[data-new-jewelry]').forEach(b=>b.onclick=()=>openJewelry());$$('[data-new-appointment]').forEach(b=>b.onclick=()=>openAppointment());$$('[data-new-gallery]').forEach(b=>b.onclick=()=>openGallery());$$('[data-new-promotion]').forEach(b=>b.onclick=()=>openPromotion());$$('[data-new-staff]').forEach(b=>b.onclick=()=>openStaff());$$('[data-new-client]').forEach(b=>b.onclick=()=>openClient());$$('[data-new-transaction]').forEach(b=>b.onclick=()=>{const f=$('#transactionForm');f.reset();$('#transactionDate').value=todayIso();modal('#transactionModal')});$$('[data-block-time]').forEach(b=>b.onclick=()=>{const f=$('#blockForm');f.reset();$('#blockDate').value=todayIso();fillBlockStaff();$('#blockTimeField').classList.remove('hidden');modal('#blockModal')});
async function prepareUpload(file,folder,previewId){if(!file)return'';try{const url=window.RassRemote?.configured()&&RassRemote.adminMode?await RassRemote.uploadImage(file,folder):await fileToDataURL(file);preview(previewId,url);return url}catch(err){console.error(err);toast('Não foi possível enviar a imagem.');return''}}
$('#serviceImageFile').onchange=async e=>{pendingServiceImage=await prepareUpload(e.target.files[0],'servicos','#servicePreview')};$('#jewelryImageFile').onchange=async e=>{pendingJewelryImage=await prepareUpload(e.target.files[0],'joias','#jewelryPreview')};$('#galleryImageFile').onchange=async e=>{pendingGalleryImage=await prepareUpload(e.target.files[0],'galeria','#galleryPreview')};
$('#serviceForm').onsubmit=e=>{e.preventDefault();const a=all('services'),id=$('#serviceId').value||D.uid('srv'),old=a.find(x=>x.id===id),fallbackImage=$('#serviceType').value==='Unhas'?'assets/images/nails-gel.jpg':'assets/images/helix.jpg',item={id,type:$('#serviceType').value,name:$('#serviceName').value.trim(),category:$('#serviceCategory').value.trim()||$('#serviceType').value,price:Number($('#servicePrice').value||0),duration:Number($('#serviceDuration').value||60),description:$('#serviceDescription').value.trim(),image:pendingServiceImage||$('#serviceImage').value.trim()||old?.image||fallbackImage,active:$('#serviceActive').checked,featured:$('#serviceFeatured').checked};const i=a.findIndex(x=>x.id===id);if(i>=0)a[i]=item;else a.push(item);set('services',a);pendingServiceImage='';closeAll();renderAll();toast('Serviço salvo.')};
$('#jewelryForm').onsubmit=e=>{e.preventDefault();const a=all('jewelry'),id=$('#jewelryId').value||D.uid('j'),old=a.find(x=>x.id===id),item={id,name:$('#jewelryName').value.trim(),category:$('#jewelryCategory').value.trim(),material:$('#jewelryMaterial').value.trim(),price:Number($('#jewelryPrice').value||0),qty:Number($('#jewelryQty').value||0),description:$('#jewelryDescription').value.trim(),image:pendingJewelryImage||$('#jewelryImage').value.trim()||old?.image||'assets/images/joia-ponto-luz.svg',active:$('#jewelryActive').checked};const i=a.findIndex(x=>x.id===id);if(i>=0)a[i]=item;else a.push(item);set('jewelry',a);pendingJewelryImage='';closeAll();renderAll();toast('Joia salva.')};
$('#appType').onchange=()=>fillAppointmentOptions($('#appType').value);$('#appointmentForm').onsubmit=e=>{e.preventDefault();const a=all('appointments'),id=$('#appointmentId').value||D.uid('a'),old=a.find(x=>x.id===id),srv=serviceById($('#appService').value),st=staffById($('#appStaff').value);const item={...(old||{}),id,name:$('#appName').value.trim(),phone:$('#appPhone').value.trim(),email:$('#appEmail').value.trim(),type:$('#appType').value,serviceId:srv?.id||'',service:srv?.name||'',staffId:st?.id||'',staff:st?.name||'',date:$('#appDate').value,time:$('#appTime').value,amount:Number($('#appAmount').value||0),status:$('#appStatus').value,payment:$('#appPayment').value,notes:$('#appNotes').value.trim(),createdAt:old?.createdAt||D.nowIso(),source:old?.source||'Admin'};const conflict=a.some(x=>x.id!==id&&x.date===item.date&&x.time===item.time&&x.staffId===item.staffId&&!['Cancelado','Recusado'].includes(x.status));if(conflict&&!confirm('Já existe um agendamento nesse horário para essa profissional. Salvar mesmo assim?'))return;const i=a.findIndex(x=>x.id===id);if(i>=0)a[i]=item;else a.push(item);set('appointments',a);const cli=D.upsertClient({name:item.name,phone:item.phone,email:item.email});item.clientId=cli?.id;set('appointments',a);if(item.status==='Concluído'&&Number(item.amount)>0){const tx=all('transactions');if(!tx.some(t=>t.appointmentId===item.id)){tx.push({id:D.uid('tx'),type:'entrada',date:item.date,description:`${item.service} · ${item.name}`,amount:item.amount,payment:item.payment||'Não definido',appointmentId:item.id,createdAt:D.nowIso()});set('transactions',tx)}}closeAll();renderAll();toast('Agendamento salvo.')};
$('#blockAllDay').onchange=()=>$('#blockTimeField').classList.toggle('hidden',$('#blockAllDay').checked);$('#blockForm').onsubmit=e=>{e.preventDefault();if(!$('#blockAllDay').checked&&!$('#blockTime').value){alert('Escolha um horário ou bloqueie o dia inteiro.');return}D.push('blocked',{id:D.uid('blk'),date:$('#blockDate').value,staffId:$('#blockStaff').value,allDay:$('#blockAllDay').checked,time:$('#blockAllDay').checked?'':$('#blockTime').value,reason:$('#blockReason').value.trim(),createdAt:D.nowIso()});closeAll();renderAll();toast('Agenda bloqueada.')};
$('#galleryForm').onsubmit=e=>{e.preventDefault();const a=all('gallery'),id=$('#galleryId').value||D.uid('g'),old=a.find(x=>x.id===id),item={id,type:$('#galleryType').value,title:$('#galleryTitle').value.trim(),image:pendingGalleryImage||$('#galleryImage').value.trim()||old?.image||'assets/images/helix.jpg',active:$('#galleryActive').checked,featured:$('#galleryFeatured').checked,credit:old?.credit||''};const i=a.findIndex(x=>x.id===id);if(i>=0)a[i]=item;else a.push(item);set('gallery',a);pendingGalleryImage='';closeAll();renderAll();toast('Galeria atualizada.')};
$('#promotionForm').onsubmit=e=>{e.preventDefault();const a=all('promotions'),id=$('#promotionId').value||D.uid('promo'),old=a.find(x=>x.id===id),item={id,type:$('#promotionType').value,discount:$('#promotionDiscount').value.trim(),title:$('#promotionTitle').value.trim(),description:$('#promotionDescription').value.trim(),startDate:$('#promotionStart').value,endDate:$('#promotionEnd').value,active:$('#promotionActive').checked,createdAt:old?.createdAt||D.nowIso()};const i=a.findIndex(x=>x.id===id);if(i>=0)a[i]=item;else a.push(item);set('promotions',a);closeAll();renderAll();toast('Promoção salva.')};
$('#staffForm').onsubmit=e=>{e.preventDefault();const specs=[];if($('#staffPiercing').checked)specs.push('Piercing');if($('#staffNails').checked)specs.push('Unhas');if(!specs.length){alert('Marque pelo menos uma área.');return}const a=all('staff'),id=$('#staffId').value||D.uid('staff'),old=a.find(x=>x.id===id),item={id,name:$('#staffName').value.trim(),phone:$('#staffPhone').value.trim(),specialties:specs,notes:$('#staffNotes').value.trim(),active:$('#staffActive').checked};const i=a.findIndex(x=>x.id===id);if(i>=0)a[i]=item;else a.push(item);set('staff',a);closeAll();renderAll();toast('Profissional salva.')};
$('#transactionForm').onsubmit=e=>{e.preventDefault();D.push('transactions',{id:D.uid('tx'),type:$('#transactionType').value,date:$('#transactionDate').value,description:$('#transactionDescription').value.trim(),amount:Number($('#transactionAmount').value||0),payment:$('#transactionPayment').value,createdAt:D.nowIso()});closeAll();renderAll();toast('Lançamento registrado.')};
$('#clientForm').onsubmit=e=>{e.preventDefault();const a=all('clients'),id=$('#clientId').value||D.uid('cli'),old=a.find(x=>x.id===id),item={...(old||{}),id,name:$('#clientAdminName').value.trim(),phone:$('#clientAdminPhone').value.trim(),email:$('#clientAdminEmail').value.trim(),notes:$('#clientAdminNotes').value.trim(),createdAt:old?.createdAt||D.nowIso(),lastSeen:D.nowIso()};const i=a.findIndex(x=>x.id===id);if(i>=0)a[i]=item;else a.push(item);set('clients',a);closeAll();renderAll();toast('Cliente salvo.')};
}
function fillBlockStaff(){$('#blockStaff').innerHTML='<option value="">Todas as profissionais</option>'+all('staff').filter(s=>s.active!==false).map(s=>`<option value="${s.id}">${safe(s.name)}</option>`).join('')}
function initSettings(){$('#siteModeForm').onsubmit=e=>{e.preventDefault();const s=all('settings');s.siteOpen=$('#settingSiteOpen').checked;s.siteNotice=$('#settingSiteNotice').value.trim();s.lowStockThreshold=Number($('#settingLowStock').value||2);set('settings',s);renderAll();toast('Controle do site salvo.')};$('#settingsForm').onsubmit=e=>{e.preventDefault();const s=all('settings');Object.assign(s,{studioName:$('#settingStudioName').value.trim(),instagram:$('#settingInstagram').value.trim(),instagramUrl:$('#settingInstagramUrl').value.trim(),whatsapp:$('#settingWhatsapp').value.trim(),location:$('#settingLocation').value.trim(),hours:$('#settingHours').value.trim()});set('settings',s);toast('Informações salvas.')};$('#heroForm').onsubmit=e=>{e.preventDefault();const s=all('settings');s.heroEyebrow=$('#settingHeroEyebrow').value.trim();s.heroLine1=$('#settingHeroLine1').value.trim();s.heroLine2=$('#settingHeroLine2').value.trim();s.heroLine3=$('#settingHeroLine3').value.trim();s.heroSubtitle=$('#settingHeroSubtitle').value.trim();s.heroPrimary=$('#settingHeroPrimary').value.trim();s.heroSecondary=$('#settingHeroSecondary').value.trim();s.showJewelry=$('#settingShowJewelry').checked;s.showGallery=$('#settingShowGallery').checked;s.showFaq=$('#settingShowFaq').checked;set('settings',s);toast('Visual do site atualizado.')};$('#availabilityForm').onsubmit=e=>{e.preventDefault();const s=all('settings');s.workDays=$$('#dayChecks input:checked').map(i=>Number(i.value));s.startHour=Number($('#settingStartHour').value||9);s.endHour=Number($('#settingEndHour').value||18);s.interval=Number($('#settingInterval').value||60);set('settings',s);toast('Disponibilidade salva.')}}
function initRemotePassword(){
  const form=$('#passwordForm'),emailInput=$('#profileEmail'),saveEmail=$('#saveEmailBtn'),help=$('#accessHelp');if(!form)return;
  RassRemote.getAccessProfile().then(p=>{if(emailInput&&p?.email)emailInput.value=p.email}).catch(()=>{});
  if(help)help.textContent='Protegido pelo Supabase. Use senha exclusiva com 12+ caracteres, maiúscula, minúscula, número e símbolo.';
  if(saveEmail)saveEmail.onclick=async()=>{
    saveEmail.disabled=true;
    try{const current=$('#currentPassword').value;const data=await RassRemote.updateEmail(emailInput.value,current);const email=data?.user?.email||emailInput.value.trim();emailInput.value=email;$('#currentPassword').value='';toast('Pedido de alteração de e-mail enviado. Confira o novo endereço se houver confirmação.')}catch(err){alert(err?.message||'Não foi possível alterar o e-mail.')}finally{saveEmail.disabled=false}
  };
  form.onsubmit=async e=>{
    e.preventDefault();const current=$('#currentPassword').value,newPass=$('#newPassword').value,confirmPass=$('#confirmPassword').value;
    if(newPass!==confirmPass){alert('As novas senhas não coincidem.');return}
    try{await RassRemote.updatePassword(current,newPass);alert('Senha alterada. Por segurança, todas as sessões foram encerradas. Entre novamente.');location.reload()}catch(err){alert(err?.message||'Não foi possível alterar a senha.')}
  };
}

async function refreshMfaPanel(){
  const badge=$('#mfaStatusBadge'),off=$('#mfaDisabledBox'),on=$('#mfaEnabledBox'),enroll=$('#mfaEnrollBox');if(!badge||!window.RassRemote?.adminMode)return;
  try{const status=await RassRemote.getMfaStatus();enroll?.classList.add('hidden');if(status.enabled){badge.textContent='2FA ATIVO';badge.className='access-secure-badge is-on';off?.classList.add('hidden');on?.classList.remove('hidden')}else{badge.textContent='2FA OPCIONAL';badge.className='access-secure-badge is-off';on?.classList.add('hidden');off?.classList.remove('hidden')}}catch{badge.textContent='INDISPONÍVEL'}
}
function initMfaSettings(){
  $('#enableMfaBtn')?.addEventListener('click',async()=>{const b=$('#enableMfaBtn');b.disabled=true;try{const data=await RassRemote.enrollMfa();pendingMfaFactor=data.id;$('#mfaQr').src=data.qr;$('#mfaSecret').textContent=data.secret;$('#mfaDisabledBox').classList.add('hidden');$('#mfaEnrollBox').classList.remove('hidden');$('#mfaEnrollCode').focus()}catch(err){alert(err?.message||'Não foi possível iniciar o 2FA.')}finally{b.disabled=false}});
  $('#verifyMfaEnrollBtn')?.addEventListener('click',async()=>{const b=$('#verifyMfaEnrollBtn');if(!pendingMfaFactor)return;b.disabled=true;try{await RassRemote.verifyMfaEnrollment(pendingMfaFactor,$('#mfaEnrollCode').value);pendingMfaFactor='';$('#mfaEnrollCode').value='';toast('Verificação em duas etapas ativada.');await refreshMfaPanel()}catch(err){alert(err?.message||'Código inválido.')}finally{b.disabled=false}});
  $('#cancelMfaEnrollBtn')?.addEventListener('click',()=>{pendingMfaFactor='';$('#mfaEnrollBox').classList.add('hidden');$('#mfaDisabledBox').classList.remove('hidden')});
  $('#disableMfaBtn')?.addEventListener('click',async()=>{if(!confirm('Desativar a verificação em duas etapas reduz a segurança da conta. Continuar?'))return;const b=$('#disableMfaBtn');b.disabled=true;try{await RassRemote.disableMfa();toast('2FA desativado.');await refreshMfaPanel()}catch(err){alert(err?.message||'Não foi possível desativar o 2FA.')}finally{b.disabled=false}});
}

function initFilters(){
  const rerenderAppointments=()=>renderAppointments();
  ['appointmentView','appointmentDateFilter','appointmentStatusFilter','appointmentTypeFilter'].forEach(id=>{const el=$('#'+id);if(el)el.addEventListener('change',rerenderAppointments)});
  $('#clearAppointmentFilters')?.addEventListener('click',()=>{['appointmentView','appointmentDateFilter','appointmentStatusFilter','appointmentTypeFilter'].forEach(id=>{const el=$('#'+id);if(el)el.value=''});renderAppointments()});
  $('#serviceAdminFilter')?.addEventListener('change',renderServices);
  $('#galleryAdminFilter')?.addEventListener('change',renderGalleryAdmin);
  $('#financeMonth')?.addEventListener('change',renderFinance);
}

function initNotifications(){
  $('#markAllRead')?.addEventListener('click',()=>{const notes=all('notifications').map(n=>({...n,read:true}));set('notifications',notes);renderAll();toast('Notificações marcadas como lidas.')});
  $('#clearNotifications')?.addEventListener('click',()=>{if(!confirm('Limpar todas as notificações do painel?'))return;all('notifications').slice().forEach(n=>D.remove('notifications',n.id,false));set('notifications',[]);renderAll();toast('Notificações removidas.')});
  $('#emptyTrash')?.addEventListener('click',()=>{if(!confirm('Esvaziar a lixeira local definitivamente?'))return;set('trash',[]);renderTrash();toast('Lixeira esvaziada.')});
}

function initBackup(){
  const exportBtn=$('#exportBtn');
  if(exportBtn)exportBtn.addEventListener('click',()=>{
    const names=['settings','services','jewelry','appointments','quotes','clients','gallery','promotions','staff','blocked','transactions','notifications'];
    const snapshot={version:'Rass Studio v4.8',exportedAt:new Date().toISOString(),data:Object.fromEntries(names.map(n=>[n,all(n)]))};
    const blob=new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
    a.href=url;a.download=`rass-studio-backup-${todayIso()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Backup exportado.')
  });
  const importInput=$('#importInput');
  if(importInput){importInput.disabled=true;importInput.title='Importação direta desativada na versão online por segurança.'}
  const resetBtn=$('#resetBtn');if(resetBtn)resetBtn.remove();
}

function initGlobalSearch(){
  const input=$('#globalSearch'),box=$('#globalSearchResults');if(!input||!box)return;
  const openResult=(tab)=>{showTab(tab);box.classList.add('hidden');input.value=''};
  input.addEventListener('input',()=>{
    const q=input.value.trim().toLowerCase();if(q.length<2){box.classList.add('hidden');box.innerHTML='';return}
    const results=[];
    all('clients').forEach(x=>{if([x.name,x.phone,x.email].some(v=>String(v||'').toLowerCase().includes(q)))results.push({tab:'clients',label:x.name||'Cliente',meta:x.phone||x.email||'Cliente'})});
    all('appointments').forEach(x=>{if([x.name,x.service,x.phone].some(v=>String(v||'').toLowerCase().includes(q)))results.push({tab:'appointments',label:x.name||'Agendamento',meta:`${x.service||''} · ${fmtDate(x.date)}`})});
    all('services').forEach(x=>{if([x.name,x.type,x.category].some(v=>String(v||'').toLowerCase().includes(q)))results.push({tab:'services',label:x.name||'Serviço',meta:x.type||'Serviço'})});
    all('jewelry').forEach(x=>{if([x.name,x.category,x.material].some(v=>String(v||'').toLowerCase().includes(q)))results.push({tab:'jewelry',label:x.name||'Joia',meta:x.category||'Joia'})});
    const shown=results.slice(0,8);box.innerHTML=shown.length?shown.map((r,i)=>`<button type="button" data-search-result="${i}"><strong>${safe(r.label)}</strong><span>${safe(r.meta)}</span></button>`).join(''):'<div class="search-empty">Nada encontrado.</div>';
    box.classList.remove('hidden');$$('[data-search-result]').forEach(b=>b.onclick=()=>openResult(shown[Number(b.dataset.searchResult)].tab));
  });
  document.addEventListener('pointerdown',e=>{if(!box.contains(e.target)&&e.target!==input)box.classList.add('hidden')});
  input.addEventListener('keydown',e=>{if(e.key==='Escape')box.classList.add('hidden')});
}

document.addEventListener('DOMContentLoaded',async()=>{document.addEventListener('rass-sync-error',e=>toast('Erro ao sincronizar '+(e.detail?.name||'dados')+'. Tente novamente.'));await initLogin();initNav();initForms();initSettings();initRemotePassword();initMfaSettings();initFilters();initNotifications();initBackup();initGlobalSearch();});
